add_action( 'init', 'perfectpixel_view_product_button_setup' );

function perfectpixel_view_product_button_setup() {
	remove_action( 'woocommerce_after_shop_loop_item', 'woocommerce_template_loop_add_to_cart', 10 );
	add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_view_product_button', 10 );
}

function perfectpixel_view_product_button() {
	global $product;
	if ( $product ) {
		printf( '<a href="%s" class="button">%s</a>', esc_url( $product->get_permalink() ), esc_html( '{{view_product_label}}' ) );
	}
}
